        choices=[
            'add', 'subtract', 'multiply', 'divide', 'power', 'modulo', 
            'evaluate', 'memory_store', 'memory_recall', 'memory_clear', 
            'get_history', 'clear_history'
        ], 
        required=True, 
        help="Calculator operation to perform"
    )
    parser.add_argument("--a", type=float, default=0.0, help="First operand or memory value")
    parser.add_argument("--b", type=float, default=0.0, help="Second operand")
    parser.add_argument("--expr", type=str, help="Math expression for evaluate")

    args = parser.parse_args()

    try:
        if args.op == 'evaluate':
            if not args.expr:
                print("Error: --expr is required for evaluate.")
                return
            result = calc.evaluate(args.expr)
            print(f"Result: {result}")

        elif args.op == 'memory_store':
            calc.memory_store(args.a)
            print(f"Stored {args.a} in memory.")

        elif args.op == 'memory_recall':
            print(f"Memory: {calc.memory_recall()}")

        elif args.op == 'memory_clear':
