import argparse
from operations import Calculator

def main() -> None:
    """Main CLI entry point for the calculator, supporting all operations."""
    parser = argparse.ArgumentParser(description="CLI Calculator")
    parser.add_argument(
        "--op", 
        choices=[
            "add", "subtract", "multiply", "divide", "power", "modulo", 
            "memory_store", "memory_recall", "memory_clear", 
            "get_history", "clear_history", "evaluate"
        ], 
        required=True,
        help="Arithmetic or calculator operation to perform"
    )
    parser.add_argument("--a", type=float, help="First operand or value for memory_store")
    parser.add_argument("--b", type=float, help="Second operand")
    parser.add_argument("--expr", type=str, help="Expression string for evaluate")

    args = parser.parse_args()
    calc = Calculator()

    try:
        if args.op in ["add", "subtract", "multiply", "divide", "power", "modulo"]:
            if args.a is None or args.b is None:
                print("Error: Two operands (--a and --b) are required for this operation.")
                return
            method = getattr(calc, args.op)
            result = method(args.a, args.b)
            print(f"Result: {result}")

        elif args.op == "memory_store":
            if args.a is None:
                print("Error: An operand (--a) is required for memory_store.")
                return
            calc.memory_store(args.a)
            print("Value stored in memory.")

        elif args.op == "evaluate":
            if not args.expr:
                print("Error: An expression (--expr) is required for evaluation.")
                return
            result = calc.evaluate(args.expr)
            print(f"Result: {result}")

        elif args.op in ["memory_recall", "memory_clear", "get_history", "clear_history"]:
            method = getattr(calc, args.op)
            result = method()
            if result is not None:
                print(f"Result: {result}")
            else:
                print(f"Operation {args.op} completed.")

    except ValueError as e:
        print(f"Error: {e}")
    except TypeError as e:
        print(f"TypeError: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
    main()

